Translate the following GNU C++ code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include<cstdio>
#include<cstring>
#include<queue>
#include<vector>
#include<climits>
using namespace std;

const int INF = 1e9;
const int dx[4] = {0, 0, -1, 1};
const int dy[4] = {1, -1, 0, 0};

int n, t;
char grid[15][15], target[15][15];
int distFromStart[15][15], distToTarget[15][15];
int id[15][15], tot;
int source, sink;

struct Edge {
    int to, capacity, flow;
    Edge(int t, int c) : to(t), capacity(c), flow(0) {}
};

vector<Edge> edges;
vector<int> adj[3005];

void addEdge(int u, int v, int cap) {
    adj[u].push_back(edges.size());
    edges.emplace_back(v, cap);
    adj[v].push_back(edges.size());
    edges.emplace_back(u, 0);
}

bool bfsDist(int startDist[][15], int sx, int sy) {
    queue<pair<int, int>> q;
    memset(startDist, 0x3f, sizeof(int) * 15 * 15);
    if (sx >= 0 && sx < n && sy >= 0 && sy < n && grid[sx][sy] != '#') {
        startDist[sx][sy] = 0;
        q.push({sx, sy});
    }
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        for (int i = 0; i < 4; ++i) {
            int nx = x + dx[i], ny = y + dy[i];
            if (nx >= 0 && nx < n && ny >= 0 && ny < n && 
                grid[nx][ny] >= '0' && grid[nx][ny] <= '9' &&
                startDist[nx][ny] > startDist[x][y] + 1) {
                startDist[nx][ny] = startDist[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
    return true;
}

bool levelGraph[3005];
int ptr[3005];

bool bfsLevel() {
    memset(levelGraph, 0, sizeof(levelGraph));
    queue<int> q;
    q.push(source);
    levelGraph[source] = true;
    ptr[source] = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int idx : adj[u]) {
            auto& e = edges[idx];
            if (!levelGraph[e.to] && e.capacity > e.flow) {
                levelGraph[e.to] = true;
                ptr[e.to] = 0;
                q.push(e.to);
            }
        }
    }
    return levelGraph[sink];
}

int dfs(int u, int flow) {
    if (u == sink || flow == 0) return flow;
    for (int& i = ptr[u]; i < (int)adj[u].size(); ++i) {
        int idx = adj[u][i];
        auto& e = edges[idx];
        if (levelGraph[e.to] && e.capacity > e.flow) {
            int pushed = dfs(e.to, min(flow, e.capacity - e.flow));
            if (pushed > 0) {
                e.flow += pushed;
                edges[idx ^ 1].flow -= pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int maxFlow() {
    int flow = 0;
    while (bfsLevel()) {
        int pushed;
        while ((pushed = dfs(source, INF)) > 0) {
            flow += pushed;
        }
    }
    return flow;
}

int main() {
    scanf("%d%d", &n, &t);
    for (int i = 0; i < n; ++i) scanf("%s", grid[i]);
    for (int i = 0; i < n; ++i) scanf("%s", target[i]);

    int sx = -1, sy = -1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 'Z') {
                sx = i; sy = j;
                grid[i][j] = '0';
            }
            id[i][j] = ++tot;
        }
    }

    bfsDist(distFromStart, sx, sy);

    source = 2 * tot + 1;
    sink = source + 1;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] >= '1' && grid[i][j] <= '9') {
                addEdge(source, id[i][j], grid[i][j] - '0');
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (target[i][j] >= '1' && target[i][j] <= '9') {
                addEdge(id[i][j] + tot, sink, target[i][j] - '0');
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] >= '1' && grid[i][j] <= '9') {
                queue<pair<int, int>> q;
                int dist[15][15];
                memset(dist, 0x3f, sizeof(dist));
                dist[i][j] = 0;
                q.push({i, j});
                while (!q.empty()) {
                    auto [x, y] = q.front(); q.pop();
                    for (int k = 0; k < 4; ++k) {
                        int nx = x + dx[k], ny = y + dy[k];
                        if (nx >= 0 && nx < n && ny >= 0 && ny < n &&
                            grid[nx][ny] >= '0' && grid[nx][ny] <= '9' &&
                            dist[nx][ny] > dist[x][y] + 1) {
                            dist[nx][ny] = dist[x][y] + 1;
                            q.push({nx, ny});
                        }
                    }
                }
                for (int x = 0; x < n; ++x) {
                    for (int y = 0; y < n; ++y) {
                        if (target[x][y] >= '1' && target[x][y] <= '9' &&
                            dist[x][y] <= t && dist[x][y] <= distFromStart[x][y]) {
                            addEdge(id[i][j], id[x][y] + tot, INF);
                        }
                    }
                }
            }
        }
    }

    printf("%d\n", maxFlow());
    return 0;
}
